"""Bind current two-case baseline proofs, preserving partial delivery status."""
from hashlib import sha256
import json
from pathlib import Path
from shutil import copyfile
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
def sha(p): return sha256(Path(p).read_bytes()).hexdigest()
def bind():
    path=HERE/'execution-manifest.json'; manifest=json.loads(path.read_text())
    for entry in manifest['cases']:
        side=entry['case_id'].rsplit('_',1)[-1]
        if side not in ('right','left'): raise ValueError('Only baseline pair supported')
        base=ROOT/f'.runtime-work/c230259-baseline-{side}'
        compat=Path(str(base)+'-compat-4')
        saved=Path(str(base)+'-saved-3/v0001')
        offline=Path(str(base)+'-offline-3/offline.log')
        copies={
            f'baseline-{side}-compatibility.json':compat/'compatibility.json',
            f'baseline-{side}-compat-analysis.log':compat/'compatibility-analysis.log',
            f'baseline-{side}-negative.log':compat/'negative-analysis.log',
            f'baseline-{side}-offline-tests.log':offline,
            f'baseline-{side}-saved-processing.json':saved/'processing.json',
            f'baseline-{side}-saved-analysis.log':saved/'analysis.log'}
        for name,src in copies.items(): copyfile(src,HERE/name)
        receipt=json.loads((HERE/f'baseline-{side}-compatibility.json').read_text())
        if receipt['construction_sha256']!=entry['construction_sha256']: raise ValueError('Stale baseline construction')
        saved_receipt=json.loads((HERE/f'baseline-{side}-saved-processing.json').read_text())
        if saved_receipt['missing_evidence'] or not saved_receipt['originals_preserved']:
            raise ValueError('Incomplete saved baseline')
        entry['acquisition']={'right_half_observation':{
            'entrypoint':'runner.py','method':'20 Hz Native full-body road reference recorder',
            'evidence':'ego_road_frames.jsonl, road_exception_context.json, trace.jsonl, video_frames.jsonl'}}
        entry['offline']={'command':f'.venv-cpu/bin/python runtime.py offline --manifest work/{HERE.name}/execution-manifest.json --case {entry["case_id"]} --output .runtime-work/c230259-baseline-{side}-offline-3',
                          'exit_code':0,'log':f'baseline-{side}-offline-tests.log',
                          'log_sha256':sha(HERE/f'baseline-{side}-offline-tests.log'),
                          'construction_sha256':entry['construction_sha256']}
        entry['compatibility']={'receipt':f'baseline-{side}-compatibility.json',
                                'sha256':sha(HERE/f'baseline-{side}-compatibility.json'),
                                'log':f'baseline-{side}-compat-analysis.log',
                                'negative_log':f'baseline-{side}-negative.log'}
        entry['negative']={'log':f'baseline-{side}-negative.log'}
        entry['post_capture']={'recorded_only':True,
            'command':f'.venv-cpu/bin/python runtime.py process-saved --manifest work/{HERE.name}/execution-manifest.json --case {entry["case_id"]} --attempt "$ATTEMPT" --output "$PROCESSING_OUTPUT" --library runtime/library --validator .runtime-work/fire-decoder/.lake/build/bin/adapterCheck',
            'feedback_command':'cat "$PROCESSING_OUTPUT/v0001/feedback.json"',
            'test_log':f'baseline-{side}-saved-current.log',
            'test_log_sha256':sha(HERE/f'baseline-{side}-saved-current.log'),
            'test_exit_code':0}
    path.write_text(json.dumps(manifest,indent=2)+'\n')
    return {'manifest_sha256':sha(path),'cases':len(manifest['cases'])}
if __name__=='__main__': print(json.dumps(bind()))

"""Bind current six-case CPU proof receipts into the exact execution manifest."""

from __future__ import annotations

from copy import deepcopy
from hashlib import sha256
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent


def read(path):
    return json.loads(Path(path).read_text())


def digest(path):
    return sha256(Path(path).read_bytes()).hexdigest()


def main():
    delivery = read(HERE / "delivery-construction-manifest.json")
    previous = read(HERE / "execution-manifest.json")
    old = {row["case_id"]: row for row in previous["cases"]}
    proofs = {row["case_id"]: row for row in read(HERE / "delivery-case-proofs.json")["cases"]}
    entries = []
    for source in delivery["cases"]:
        case = source["case_id"]
        proof = proofs[case]
        if proof["construction_sha256"] != source["construction_sha256"]:
            raise ValueError("Primary proof construction changed")
        row = deepcopy(source)
        row["offline"] = {"command": proof["offline_command"], "exit_code": 0,
                          "log": proof["offline_log"]["path"],
                          "log_sha256": proof["offline_log"]["sha256"],
                          "construction_sha256": row["construction_sha256"]}
        row["compatibility"] = {"receipt": proof["compatibility_receipt"]["path"],
                                "sha256": proof["compatibility_receipt"]["sha256"],
                                "log": proof["analysis_log"]["path"]}
        row["negative"] = {"log": proof["negative_log"]["path"]}
        if case in old:
            for key in ("physical_preparation", "delivery_acceptance", "acquisition"):
                if key in old[case]:
                    row[key] = old[case][key]
        else:
            row["acquisition"] = deepcopy(old[next(iter(old))]["acquisition"])
        entries.append(row)
    previous["cases"] = entries
    (HERE / "execution-manifest.json").write_text(json.dumps(previous, indent=2) + "\n")
    print("Bound current offline and compatibility receipts for", len(entries), "cases")


if __name__ == "__main__":
    main()

"""Distinct source-shaped lateral trajectories for the three passing sweep controls.

Diagnostic fixtures only. They do not constitute physical Native realization.
"""
import copy
from hashlib import sha256
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
BASE = json.loads((HERE / 'lane-diagnostic-passing_boundary_crossing.json').read_text())
POINTS = {'passing_excursion-0000': .4,
          'passing_excursion-0001': .8,
          'passing_excursion-0002': .6}

def write(path, value):
    path.write_text(json.dumps(value, indent=2) + '\n')

def sha(path):
    return sha256(path.read_bytes()).hexdigest()

def rows(value):
    return [json.loads(line) for line in value.splitlines() if line.strip()]

def encode(value):
    return ''.join(json.dumps(row) + '\n' for row in value)

def bind_pose(container, source, z):
    x = sum(point[0] for point in source['ego_corners_xy_m']) / 4
    y = sum(point[1] for point in source['ego_corners_xy_m']) / 4
    vertices = [[a, b, z] for a, b in source['ego_corners_xy_m'] for z in (0., 1.5)]
    if 'ego' in container:
        container['ego'].update(position_m=[x, y, z], body_vertices_m=vertices)
    observed = container.get('original_observations') or container.get('observed_evidence')
    if observed:
        for actor in observed.get('participants', []):
            if actor.get('actor_id') == source['ego_id']:
                actor.update(position_m=[x, y, z], body_vertices_m=vertices)

def build(suffix, fraction):
    data = copy.deepcopy(BASE)
    originals = rows(data['files']['marked_lane_sources.jsonl'])
    traces = rows(data['files']['trace.jsonl'])
    evidence = rows(data['files']['capture/evidence.jsonl'])
    if len(originals) != len(traces):
        raise ValueError('Diagnostic original trajectory is incomplete')
    by_frame = {}
    for i, (original, trace) in enumerate(zip(originals, traces)):
        lane = original['lane']
        polygon = lane['polygon_xy_m']
        heading = lane['lane_heading_xy']
        center = [sum(point[axis] for point in polygon) / len(polygon) for axis in (0, 1)]
        normal = (-heading[1], heading[0])
        target_offset = lane['lane_width_m'] * fraction * max(0., (i - 3) / (len(originals) - 4))
        old_center = [sum(point[axis] for point in original['ego_corners_xy_m']) / 4 for axis in (0, 1)]
        new_center = [center[axis] + normal[axis] * target_offset for axis in (0, 1)]
        delta = [new_center[axis] - old_center[axis] for axis in (0, 1)]
        original['ego_corners_xy_m'] = [[point[axis] + delta[axis] for axis in (0, 1)] for point in original['ego_corners_xy_m']]
        trace['position']['x'], trace['position']['y'] = new_center
        if 'position_m' in trace:
            trace['position_m'][:2] = new_center
        by_frame[original['frame']] = (original, trace['position_m'][2])
    for row in evidence:
        source = by_frame.get(row.get('original_frame'))
        if source:
            bind_pose(row, *source)
    for graph in data['graphs']:
        source = by_frame.get(graph['attributes'].get('frame'))
        if source:
            bind_pose(graph['attributes'], *source)
    data['files']['marked_lane_sources.jsonl'] = encode(originals)
    data['files']['trace.jsonl'] = encode(traces)
    data['files']['capture/evidence.jsonl'] = encode(evidence)
    capture = json.loads(data['files']['capture/manifest.json'])
    capture['sources']['trace.jsonl'] = sha256(data['files']['trace.jsonl'].encode()).hexdigest()
    data['files']['capture/manifest.json'] = json.dumps(capture, indent=2) + '\n'
    data['files']['lane_fixture_provenance.json'] = json.dumps({
        'diagnostic_fixture': True,
        'case_suffix': suffix,
        'requested_crossing_fraction': fraction,
        'note': 'Synthetic source-shaped distinct lateral target; no physical Native claim.'
    }) + '\n'
    path = HERE / ('lane-diagnostic-' + suffix + '.json')
    path.write_text(json.dumps(data, separators=(',', ':')) + '\n')
    if path.stat().st_size >= 2 * 1024 * 1024:
        raise ValueError('Diagnostic bundle exceeds local source size limit')
    recipe = {
        'format': 'worker-fixture-recipe',
        'sources': [{'path': 'diagnostic-input.json', 'source': str(path.relative_to(ROOT)), 'sha256': sha(path)}],
        'generator': {'source': str(path.relative_to(ROOT)), 'sha256': sha(path)},
    }
    recipe_path = HERE / ('lane-diagnostic-' + suffix + '-recipe.json')
    write(recipe_path, recipe)
    return str(recipe_path.relative_to(ROOT))

if __name__ == '__main__':
    recipes = {suffix: build(suffix, fraction) for suffix, fraction in POINTS.items()}
    for name in ('delivery-construction-manifest.json', 'execution-manifest.json'):
        path = HERE / name
        manifest = json.loads(path.read_text())
        for entry in manifest['cases']:
            suffix = entry['case_id'].rsplit('__', 1)[-1]
            if suffix in recipes:
                entry['fixture_recipe'] = recipes[suffix]
        write(path, manifest)
    print('Built', len(recipes), 'distinct synthetic passing trajectories')
